begin;
create temporary table consent_vector_results(code text,passed boolean) on commit drop;
do $$ declare o uuid:='10000000-0000-4000-8000-000000000001'; a uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); i uuid; v jsonb; actual boolean; els jsonb:='{"patientName":true,"recipients":true,"amountAndKind":true,"purpose":true,"rightToRevoke":true,"expiration":true,"signatureAndDate":true,"redisclosureNotice":true}'; vectors jsonb:='[{"code":"active_tpo","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","expected":true},{"code":"recipient_case","type":"part2_tpo_single","recipient":" ADELANTE ","purpose":"tpo","expected":true},{"code":"wrong_recipient","type":"part2_tpo_single","recipient":"outside","purpose":"tpo","expected":false},{"code":"wrong_purpose","type":"part2_tpo_single","recipient":"Adelante","purpose":"care_coordination","expected":false},{"code":"counseling_separate","type":"counseling_notes_release","recipient":"Adelante","purpose":"tpo","expected":false},{"code":"legal_separate","type":"legal_part2_disclosure","recipient":"Adelante","purpose":"tpo","expected":false},{"code":"justice_separate","type":"po_voluntary_coordination","recipient":"Adelante","purpose":"tpo","expected":false},{"code":"advocate_separate","type":"advocate_release","recipient":"Adelante","purpose":"tpo","expected":false},{"code":"revoked","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","status":"revoked","expected":false},{"code":"expired","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","status":"expired","expected":false},{"code":"superseded","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","status":"superseded","expected":false},{"code":"legacy","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","legacy":true,"expected":false},{"code":"merge_hold","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","merge":true,"expected":false},{"code":"expiry_event","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","expiryEvent":true,"expected":false},{"code":"future","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","future":true,"expected":false},{"code":"item_included","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","item":"treatment","expected":true},{"code":"item_missing","type":"part2_tpo_single","recipient":"Adelante","purpose":"tpo","item":"outside_records","expected":false}]'; begin
insert into public.accounts(id,org_id,kind) values(a,o,'patient');
execute format('create or replace function app.account_id() returns uuid language sql stable security definer set search_path='''' as %L','select '||quote_literal(a::text)||'::uuid');
for v in select jsonb_array_elements(vectors) loop
p:=gen_random_uuid(); i:=gen_random_uuid();
insert into public.patients(id,org_id,source_key,first_name,last_name,synthetic) values(p,o,'vector_'||(v->>'code'),'Fictional','Vector',true);
insert into public.consent_records(id,org_id,patient_id,consent_type,recipients,purpose_code,items,status,effective_at,signed_at,signed_by_kind,signature_method,part2_elements,legacy_unverified,needs_review_after_merge,expiry_event_occurred_at,synthetic) values(i,o,p,'part2_tpo_single','[{"kind":"org","name":"Adelante","directoryRef":"adelante-program"}]','tpo',array['treatment'],coalesce(v->>'status','active'),case when coalesce((v->>'future')::boolean,false) then '2026-10-28T00:00:00Z'::timestamptz else '2026-10-26T00:00:00Z'::timestamptz end,'2026-10-26T00:00:00Z','staff_capture','e_sign',els,coalesce((v->>'legacy')::boolean,false),coalesce((v->>'merge')::boolean,false),case when coalesce((v->>'expiryEvent')::boolean,false) then '2026-10-27T00:00:00Z'::timestamptz else null end,true);
actual:=app.consent_covers(p,v->>'type',v->>'recipient',v->>'purpose',v->>'item','2026-10-27T12:00:00Z');
if actual is distinct from (v->>'expected')::boolean then raise exception 'consent_vector_failed %',v->>'code'; end if;
insert into consent_vector_results values(v->>'code',true);
end loop;
end $$;
select count(*) checks,count(*) filter(where passed) passed from consent_vector_results;
rollback;